#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "archive.h"
#include "archive_entry.h"

struct Buffer {
  const uint8_t *buf;
  size_t len;
};

ssize_t reader_callback(struct archive *a, void *client_data,
                        const void **block) {
  (void)a;
  struct Buffer *buffer = (struct Buffer *)client_data;
  *block = buffer->buf;
  ssize_t len = buffer->len;
  buffer->len = 0;
  printf("reader_callback: returning %zd bytes\n", len);
  return len;
}

int main(int argc, char **argv) {
  if (argc != 2) {
    fprintf(stderr, "Usage: %s <rar5_file>\n", argv[0]);
    return 1;
  }

  FILE *f = fopen(argv[1], "rb");
  if (!f) {
    fprintf(stderr, "Cannot open %s\n", argv[1]);
    return 1;
  }
  fseek(f, 0, SEEK_END);
  long len = ftell(f);
  fseek(f, 0, SEEK_SET);
  uint8_t *buf = (uint8_t *)malloc(len);
  fread(buf, 1, len, f);
  fclose(f);

  struct archive *a = archive_read_new();
  int r = archive_read_support_format_rar5(a);
  printf("archive_read_support_format_rar5: %d\n", r);

  struct Buffer buffer = {buf, (size_t)len};
  r = archive_read_open(a, &buffer, NULL, reader_callback, NULL);
  printf("archive_read_open: %d\n", r);

  struct archive_entry *entry;
  while ((r = archive_read_next_header(a, &entry)) == ARCHIVE_OK) {
    printf("Got header: %s\n", archive_entry_pathname(entry));
    char data_buffer[4096];
    while ((r = archive_read_data(a, data_buffer, sizeof(data_buffer))) > 0)
      ;
    if (r == ARCHIVE_FATAL)
      break;
  }
  printf("archive_read_next_header final: %d\n", r);
  printf("Error: %s\n", archive_error_string(a));

  archive_read_free(a);
  free(buf);
  return 0;
}
EOF
